  "st:ID": { title:"Idaho", extract:"A Mountain West state of Rockies and Snake River Plain. Boise lies in the southwest; the panhandle reaches Canadian latitudes." },
  "st:IL": { title:"Illinois", extract:"From Lake Michigan to the Ohio and Mississippi. Chicago is the northern metropolis; most of the rest is prairie and river town." },
  "st:IN": { title:"Indiana", extract:"A Midwestern state south of Lake Michigan. Indianapolis sits at the center; the south rises into hills toward the Ohio." },
