  "st:MD": { title:"Maryland", extract:"A state split by Chesapeake Bay. Baltimore is the port; Annapolis the capital. Western counties climb toward the Appalachians." },
  "st:MA": { title:"Massachusetts", extract:"New England on the Atlantic. Boston is the regional center of finance and universities; Cape Cod and the Berkshires mark the extremes." },
  "st:MI": { title:"Michigan", extract:"Two peninsulas between the Great Lakes. Detroit sits in the south; the Upper Peninsula is timber, rock, and long winters." },
  "st:MN": { title:"Minnesota", extract:"Northern plains and lakes at the headwaters of the Mississippi. Minneapolis\u2013Saint Paul is the urban core; the north is forest and iron range." },
  "st:MS": { title:"Mississippi", extract:"Follows the great river from Tennessee to the Gulf. Jackson is the capital; the Delta in the northwest is alluvial farm country." },
  "st:MO": { title:"Missouri", extract:"Between the Mississippi and the Great Plains. St. Louis and Kansas City anchor east and west; the Ozarks occupy the south." },
  "st:MT": { title:"Montana", extract:"Northern Rockies and high plains. The Continental Divide crosses the west; the east is plains and isolated ranges." },
  "st:NE": { title:"Nebraska", extract:"A plains state along the Platte. Omaha and Lincoln lie in the east; Sandhills and High Plains occupy the center and west." },
  "st:NV": { title:"Nevada", extract:"The driest U.S. state, mostly Basin and Range desert. Las Vegas and Reno are the urban exceptions." },
  "st:NH": { title:"New Hampshire", extract:"New England from the Atlantic at Portsmouth to the White Mountains. Concord is the capital; Manchester the largest city." },
  "st:NJ": { title:"New Jersey", extract:"Between New York Harbor and Delaware Bay. The north is metropolitan; the south is coastal plain and shore." },
  "st:NM": { title:"New Mexico", extract:"A high, dry Southwestern state of basin, range, and volcanic field. Santa Fe is the capital; Albuquerque the largest city, on the Rio Grande." },
  "st:NY": { title:"New York", extract:"From the Atlantic at New York City up the Hudson to the Adirondacks and Great Lakes. The city is the nation's largest." },
  "st:NC": { title:"North Carolina", extract:"From the Outer Banks across Piedmont cities to the Blue Ridge and Smokies. Raleigh and Charlotte are the political and financial centers." },
  "st:ND": { title:"North Dakota", extract:"Northern plains on the Canadian line. The Missouri cuts the west; the Red River valley in the east is rich farm country." },
  "st:OH": { title:"Ohio", extract:"A Midwestern state on Lake Erie. A belt of industrial cities faces the lake; the south drains to the Ohio River." },
  "st:OK": { title:"Oklahoma", extract:"Southern plains between Texas and Kansas. Oklahoma City and Tulsa are the urban centers; the west is high plains, the east more wooded." },
  "st:OR": { title:"Oregon", extract:"Pacific Northwest from a wet coast and Cascade volcanoes to dry plateau east of the mountains. Portland sits on the Columbia and Willamette." },
  "st:PA": { title:"Pennsylvania", extract:"From Lake Erie and the Ohio at Pittsburgh across ridges to Philadelphia on the Delaware. Harrisburg is the capital." },
  "st:RI": { title:"Rhode Island", extract:"The smallest U.S. state, on Narragansett Bay. Providence is the capital; the coast is an old maritime strip." },
  "st:SC": { title:"South Carolina", extract:"Atlantic South from barrier islands through lowcountry to Piedmont. Columbia is the capital; Charleston the historic port." },
  "st:SD": { title:"South Dakota", extract:"Northern plains crossed by the Missouri. The Black Hills rise in the west; the east is farm prairie." },
  "st:TN": { title:"Tennessee", extract:"A long east\u2013west state from the Appalachians to the Mississippi. Nashville, Memphis, and Knoxville divide its regions." },
  "st:TX": { title:"Texas", extract:"The largest of the contiguous states. Gulf coast, pine woods, prairie, and desert all occur within it. Austin is the capital; Houston, Dallas, and San Antonio the great cities." },
  "st:UT": { title:"Utah", extract:"A Mountain West state of the Wasatch Front, Great Basin, and Colorado Plateau. Salt Lake City sits beneath the Wasatch." },
  "st:VT": { title:"Vermont", extract:"A New England state between New York and New Hampshire, dominated by the Green Mountains. Montpelier is the capital; Burlington the largest city." },
  "st:VA": { title:"Virginia", extract:"From the Chesapeake and Tidewater across Piedmont to the Blue Ridge and Appalachians. Richmond is the capital." },
  "st:WA": { title:"Washington", extract:"Pacific Northwest with a wet west, Cascade volcanoes, and dry Columbia Plateau. Olympia is the capital; Seattle the largest city." },
  "st:WV": { title:"West Virginia", extract:"An Appalachian state of ridges and coal valleys. Charleston is the capital; the Ohio River forms much of the west edge." },
  "st:WI": { title:"Wisconsin", extract:"A Great Lakes state on Michigan and Superior. Madison is the capital; Milwaukee the largest city. Dairy and timber shaped its interior." },
  "st:WY": { title:"Wyoming", extract:"The least populous state, of high plains and the central Rockies. Cheyenne is the capital; Yellowstone and the Tetons occupy the northwest." },
  "cc:US": { extract:"A federal republic of fifty states and a capital district, spanning a continent between the Atlantic and Pacific plus Alaska and Hawai\u02bbi." },
